import os, glob, re

def load_grids():
    """Load all grids from the harness log including demo pairs and test input."""
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    session_file = os.path.normpath(os.path.join(d, '..', '..', 'sessions', os.path.basename(d))) + '.jsonl'

    try:
        with open(session_file, 'r') as f:
            content = f.read()

        grids = {}
        for line in content.split('\n'):
            line = line.strip()
            if not line:
                continue

            # Try to match demo/test input patterns
            # Pattern like "Demo pair <#> input (<w>x<h>):" or "Test input (<w>x<h>):"
            idx = line.find('input')
            if idx == -1:
                idx = line.find('Test input')
                if idx == -1:
                    idx = line.find('output')

            if idx == -1:
                continue

            # Check for depth 1 nesting (one more bracket)
            if line.find('input') > line.find('['):
                continue

            # Parse the label at the beginning
            label_end = line.find(':', 0)
            label = line[:label_end].strip()

            # Find the grid coordinates after the label
            row_match = re.search(r'(\d+)x(\d+):', line)
            if not row_match:
                continue

            rows, cols = int(row_match.group(1)), int(row_match.group(2))

            # Find actual label suffix
            if 'Test input' in label:
                full_label = 'Test input'
            elif 'Demo pair' in label:
                demomatch = re.search(r'Demo pair (\d+)', label)
                if demomatch:
                    full_label = f"Demo pair {demomatch.group(1)}"
                else:
                    continue
            else:
                continue

            # Extract grid rows
            grid_str = line[label_end+1:].strip()

            # Skip grids that are too large or not bids
            if rows > 30 or cols > 30:
                continue

            # Parse the grid - find all rows starting from this point
            lines_in_grid = []
            in_grid = False
            brace_count = grid_str.count('[')

            for lnum, row_line in enumerate(grid_str.split('\n')):
                if '[' in row_line or ']' in row_line or ':' in row_line:
                    # Continue processing
                    lines_in_grid.append(row_line)
                    depth_match = re.search(r'\[[^\]]*\]', row_line)
                    if depth_match:
                        brace_count += grid_str.count('[') if '[' in row_line else 0
                        if '[' in row_line:
                            brace_count += row_line.count('[')
                        if ']' in row_line:
                            brace_count -= row_line.count(']')
                    else:
                        if '[' in row_line:
                            brace_count += 1
                        if ']' in row_line:
                            brace_count -= 1
                else:
                    if '[' in row_line or ']' in row_line:
                        in_grid = True

                    depth_match = re.search(r'\[[0-9,\s]+\]', row_line)
                    if depth_match:
                        grid_str += '\n' + row_line

            # Skip this one if it's an empty string or not clear
            if not lines_in_grid:
                continue

            # Parse grid rows
            grids[full_label] = [[int(x) for x in line.split() if x.isdigit()] for line in lines_in_grid[-20:] if line.strip() and line.strip() and line.strip()[0] != '['] if line.strip()[0] != '[']

            # Try parsing type different
            try:
                grids[full_label] = [[int(x) for x in eval(line.strip())[1:-1].replace('\n','').replace('  ',' ',).split(','  ').replace('\\n','').split(',') if x.isdigit()] for line in lines_in_grid if line.strip() and line.strip()[0] == '[']
            except:
                pass

        return grids
    except Exception as e:
        print(f"Error loading grids: {e}")
        return {}

grids = load_grids()
print(f"Grids found: {list(grids.keys())}")

