import ast
def parse_grid_simple(text):
    """Simple parser for grids."""
    grids = []
    lines = text.split('\n')
    in_grid = False
    grid_lines = []

    for line in lines:
        line = line.strip()
        if not line:
            continue

        # Check if line contains a grid array
        if '[' in line and ']' in line and line.count('[') == line.count(']'):
            try:
                grid = ast.literal_eval(line)
                if isinstance(grid, list) and all(isinstance(row, list) for row in grid):
                    grids.append(grid)
            except:
                try:
                    grid = [int(x) for x in line.split()]
                    grids.append(grid)
                except:
                    pass

    return grids if grids else None

